window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[186]={"id":"186","numero":186,"titre":"Hypersensibilités et allergies chez l'enfant et l'adulte","objectifs":[{"id":"186-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des réactions d’hypersensibilité : allergique et non allergique","contenu":"<div class=\"notion-course\"><h4>Définitions et mécanismes</h4><table><thead><tr><th>Notion</th><th>Définition</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Hypersensibilité</span></td><td><span class=\"nc-red nc-bold\">Symptômes</span> reproductibles après un stimulus à une dose habituellement tolérée.</td></tr><tr><td>Allergie</td><td><span class=\"nc-red nc-bold\">Hypersensibilité</span> à mécanisme immunologique spécifique, IgE ou non IgE.</td></tr><tr><td><span class=\"nc-red nc-bold\">Sensibilisation</span></td><td>Présence d’effecteurs spécifiques, notamment test cutané/IgE spécifiques positifs ; peut rester asymptomatique.</td></tr><tr><td><span class=\"nc-brown_bg nc-bold\">Atopie</span></td><td>Prédisposition à <span class=\"nc-yellow_bg nc-bold\">produire des IgE</span> contre des allergènes environnementaux courants.</td></tr><tr><td><span class=\"nc-red nc-bold\">Hypersensibilité</span> non allergique</td><td>Mécanisme sans réponse adaptative spécifique : activation mastocytaire directe, effets <span class=\"nc-blue nc-bold\">pharmacologiques</span>, etc. Une réaction peut néanmoins être grave.</td></tr></tbody></table><table><thead><tr><th>Gell et Coombs</th><th>Mécanisme et exemples</th></tr></thead><tbody><tr><td>I</td><td>IgE, <span class=\"nc-yellow_bg\">mastocytes</span>/<span class=\"nc-yellow_bg\">basophiles</span> ; <span class=\"nc-orange_bg\">rhinite</span>, <span class=\"nc-orange_bg\">asthme allergique</span>, <span class=\"nc-red_bg\">anaphylaxie</span>. Habituellement minutes à <span class=\"nc-pink nc-bold\">quelques heures</span>.</td></tr><tr><td>II</td><td>IgG/IgM contre une cible cellulaire ; cytopénies immunes.</td></tr><tr><td>III</td><td><span class=\"nc-blue_bg nc-bold\">Complexes immuns</span>, <span class=\"nc-blue_bg nc-bold\">complément</span> ; <span class=\"nc-orange_bg\">maladie sérique</span>.</td></tr><tr><td>IV</td><td>Lymphocytes T ; <span class=\"nc-pink nc-bold\">eczéma de contact</span> et toxidermies. Délais et mécanismes variables, pas toujours granulomateux.</td></tr></tbody></table><p><span class=\"nc-red nc-bold\">Sensibilisation</span> puis phase effectrice : pontage des IgE fixées au FcεRI, libération d’<span class=\"nc-pink nc-bold\">histamine</span>/<span class=\"nc-pink nc-bold\">tryptase</span>, puis <span class=\"nc-pink_bg\">médiateurs</span> lipidiques et cytokines. <span class=\"nc-red_bg\">Bronchoconstriction</span>, <span class=\"nc-red_bg\">vasodilatation</span> et fuite capillaire expliquent les <span class=\"nc-red nc-bold\">symptômes</span>. La phase tardive d’une réaction IgE n’est pas une <span class=\"nc-red nc-bold\">hypersensibilité</span> de type IV.</p><p>La dose et les cofacteurs modulent le seuil de réaction, même en <span class=\"nc-red nc-bold\">allergie</span>. Une première <span class=\"nc-red nc-bold\">exposition</span> connue peut provoquer des <span class=\"nc-red nc-bold\">symptômes</span> après <span class=\"nc-red nc-bold\">sensibilisation</span> méconnue ou croisée. Tous les allergènes ne sont pas des protéines : certains déterminants glucidiques sont pertinents ; l’<span class=\"nc-brown_bg\">intolérance</span> au lactose n’est <span class=\"nc-red nc-bold\">pas une allergie</span>.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details><details><summary>Situations de départ LiSA</summary><p>Attendus consultés le 14 octobre 2026 et reformulés pour ces parcours. Les liens ouvrent la recherche LiSA par numéro ; une authentification UNESS peut être requise.</p><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Sp%C3%A9cial:Recherche/SDD-299\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 299 · Consultation après une réaction allergique</a></li><li><a href=\"https://livret.uness.fr/lisa/2026/Sp%C3%A9cial:Recherche/SDD-203\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 203 · Examens allergologiques</a></li></ul><p>Ces correspondances sont partielles : l’item ne couvre pas à lui seul l’ensemble de chaque situation.</p></details>","frequence":0},{"id":"186-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques des allergies aux venins d’hyménoptères : prévalence, mortalité","contenu":"<div class=\"notion-course\"><ul><li>Les réactions systémiques aux <span class=\"nc-pink nc-bold\">venins</span> concernent une minorité de la population : ordre de grandeur CEP 0,3–7,5 %, contre 10–40 % de sensibilisations selon les populations.</li><li>Abeilles, guêpes, frelons et bourdons ; <span class=\"nc-red nc-bold\">exposition</span> professionnelle/loisirs et terrain modifient le risque.</li><li>Une seule <span class=\"nc-red nc-bold\">piqûre</span> peut provoquer une anaphylaxie allergique ; de nombreuses piqûres peuvent aussi provoquer une toxicité non allergique.</li><li>Les décès sont rares mais possibles. Ne pas présenter les hyménoptères comme la principale cause pédiatrique de décès anaphylactique : l’alimentation occupe une place majeure <span class=\"nc-red_bg\">chez l’enfant</span>.</li><li>Réaction systémique sévère : bilan allergologique, recherche des facteurs de gravité dont maladie mastocytaire selon contexte. La <span class=\"nc-red nc-bold\">sensibilisation</span> n’est pas nécessairement immuable à vie.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","contenu":"<div class=\"notion-course\"><ul><li>Prévalence dépendante de l’âge, des pays et du mode de confirmation : quelques pour cent ; les déclarations spontanées surestiment souvent l’<span class=\"nc-yellow_bg\">allergie</span> confirmée.</li><li>Repères CEP français : <span class=\"nc-yellow_bg\">environ</span> 4 % à 2–5 ans, 6,8 % à 6–10 ans, 3,4 % à 11–14 ans et 2–3 % chez <span class=\"nc-red_bg\">l’adulte</span>.</li><li>Lait et <span class=\"nc-red nc-bold\">œuf</span> prédominent chez le jeune enfant ; <span class=\"nc-yellow_bg\">arachide</span> et <span class=\"nc-pink nc-bold\">fruits à coque</span> deviennent importants, avec d’autres aliments selon habitudes. Chez <span class=\"nc-red_bg\">l’adulte</span> : <span class=\"nc-pink nc-bold\">fruits à coque</span>, fruits/légumes, <span class=\"nc-pink nc-bold\">crustacés</span> et autres sources.</li><li>Lait/œuf acquièrent plus souvent une tolérance que l’arachide ou les fruits à coque ; évolution individuelle, sans âge de guérison garanti.</li><li>Mortalité rare mais risque d’anaphylaxie, retentissement nutritionnel, psychologique et social ; ne pas réduire l’évaluation à la fréquence de l’allergène.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques des hypersensibilités allergiques et non allergiques médicamenteuses : prévalence, morbidité, mortalité","contenu":"<div class=\"notion-course\"><ul><li>Les étiquettes d’allergie médicamenteuse sont fréquentes (ordre de grandeur rapporté autour de 7 %) ; seule une partie correspond à une allergie confirmée.</li><li>Réactions immédiates IgE ou non IgE ; réactions retardées à médiation cellulaire. β-lactamines, AINS, curares, certains colorants et produits de contraste sont des causes importantes.</li><li>Un produit de contraste peut provoquer une réaction allergique ou non allergique : ne pas écrire « <span class=\"nc-red nc-bold\">allergie</span> à l’iode », ni inférer le risque d’une <span class=\"nc-red nc-bold\">allergie</span> aux produits de la mer.</li><li>AINS : réactions croisées <span class=\"nc-blue nc-bold\">pharmacologiques</span> ou allergie sélective selon cas. Le paracétamol n’est pas assimilable systématiquement à un AINS.</li><li>Anaphylaxie et <span class=\"nc-red nc-bold\">toxidermies graves</span> (<span class=\"nc-red nc-bold\">DRESS</span>, Stevens–Johnson/Lyell, <span class=\"nc-red nc-bold\">PEAG</span>) imposent une prise en charge adaptée. Documenter molécule, délai, <span class=\"nc-red nc-bold\">symptômes</span>, sévérité et traitements.</li><li>Arrêt du médicament suspect, déclaration en pharmacovigilance et bilan spécialisé ; carte précisant le niveau de <span class=\"nc-red nc-bold\">certitude</span> et alternatives. Pas de réintroduction improvisée après réaction grave.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les éléments physiopathologiques des allergies aux venins d’hyménoptères : prévalence, mortalité","contenu":"<div class=\"notion-course\"><p>Le venin contient des molécules <span class=\"nc-blue nc-bold\">toxiques</span>/vasoactives et des protéines allergéniques. Après <span class=\"nc-red nc-bold\">sensibilisation</span>, une <span class=\"nc-red nc-bold\">piqûre</span> peut activer les <span class=\"nc-red nc-bold\">mastocytes</span> par les IgE <span class=\"nc-orange_bg\">spécifiques</span>. Les piqûres multiples peuvent causer une envenimation toxique, indépendamment d’une <span class=\"nc-red nc-bold\">allergie</span>.</p><ul><li>Réaction locale : douleur, <span class=\"nc-red_bg\">érythème</span>, gonflement au point de <span class=\"nc-red nc-bold\">piqûre</span>. Réaction locale étendue : extension importante prolongée, sans atteinte systémique.</li><li>Réaction systémique : urticaire généralisée et/ou atteinte respiratoire, circulatoire ou digestive. Évaluer <span class=\"nc-red nc-bold\">l’anaphylaxie</span> sur l’ensemble clinique ; ne pas attendre un grade élevé de Mueller.</li><li>Anaphylaxie : <span class=\"nc-pink nc-bold\">adrénaline IM</span> immédiate et secours ; H1/<span class=\"nc-red nc-bold\">corticoïdes</span> ne traitent pas la défaillance vitale.</li><li>L’immunothérapie aux <span class=\"nc-pink nc-bold\">venins</span> prévient efficacement les récidives chez les patients sélectionnés après bilan ; indication individualisée selon réaction, <span class=\"nc-red nc-bold\">sensibilisation</span>, <span class=\"nc-red nc-bold\">exposition</span> et risque. Ce n’est pas une garantie de guérison absolue.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://www.sfmu.org/upload/consensus/rfe_anaphylaxie_sfmu2016.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SFMU/SFA · anaphylaxie en urgence</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","contenu":"<div class=\"notion-course\"><ol><li>Anamnèse : <span class=\"nc-red nc-bold\">symptômes</span>, délai, répétition, quantité/<span class=\"nc-red nc-bold\">exposition</span>, saison, domicile, travail et cofacteurs ; confirmer <span class=\"nc-orange_bg\">rhinite</span>/asthme et rechercher les autres causes.</li><li>Prick-tests ciblés en première intention si réalisables : <span class=\"nc-red nc-bold\">sensibilisation</span> à confronter aux <span class=\"nc-red nc-bold\">symptômes</span>.</li><li>IgE <span class=\"nc-blue nc-bold\">spécifiques</span> si tests impossibles, discordants ou <span class=\"nc-blue_bg nc-bold\">complément</span> nécessaire ; dosage moléculaire dans des indications ciblées.</li><li>Provocation nasale/bronchique seulement en centre expert si le doute persiste et si le résultat change la prise en charge.</li></ol><p>Un test positif n’est pas un diagnostic clinique. Les <span class=\"nc-red nc-bold\">symptômes</span> peuvent être entretenus par une <span class=\"nc-red nc-bold\">exposition</span> répétée ; ni un délai universel &lt; 1 h ni une réaction à chaque contact ne sont exigés. IgE totales, <span class=\"nc-green nc-bold\">éosinophiles</span> et IgG ne remplacent pas ce bilan ; ils peuvent avoir d’autres indications spécialisées. La <span class=\"nc-pink nc-bold\">tryptase</span> aide l’évaluation de <span class=\"nc-red nc-bold\">l’anaphylaxie</span> et du terrain mastocytaire, sans identifier l’allergène.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux allergènes de l’allergie alimentaire IgE-dépendante","contenu":"<div class=\"notion-course\"><table><thead><tr><th>Source</th><th>À connaître</th></tr></thead><tbody><tr><td>Lait de vache</td><td>Caséines et protéines du lactosérum ; distinguer allergie et <span class=\"nc-brown_bg\">intolérance</span> au lactose.</td></tr><tr><td>Œuf</td><td>Ovomucoïde plus thermostable qu’ovalbumine ; tolérance à l’œuf cuit à évaluer individuellement.</td></tr><tr><td>Arachide</td><td>Légumineuse ; protéines de stockage dont Ara h 2. Ne pas l’assimiler à un fruit à coque.</td></tr><tr><td><span class=\"nc-orange nc-bold\">Fruits à coque</span></td><td>Noisette, noix, cajou, pistache, amande… <span class=\"nc-brown_bg\">Allergies</span> associées possibles, sans éviction de tous sur une simple <span class=\"nc-red nc-bold\">sensibilisation</span>.</td></tr><tr><td>Autres</td><td>Poissons, <span class=\"nc-pink nc-bold\">crustacés</span>, blé, <span class=\"nc-pink nc-bold\">soja</span>, sésame, moutarde, fruits et légumes selon âge/contexte.</td></tr></tbody></table><p>Une réaction IgE survient habituellement rapidement, parfois pour une faible quantité, mais le seuil et la gravité varient avec dose, exercice, alcool, AINS, infection et autres cofacteurs.</p><h4>APLV et alimentation</h4><ul><li>Formes IgE et non IgE : <span class=\"nc-red nc-bold\">symptômes</span> et bilan diffèrent. Le SEIPA peut donner vomissements retardés répétés, <span class=\"nc-brown_bg\">pâleur</span> et <span class=\"nc-brown_bg\">léthargie</span> sans urticaire ; ce n’est pas un diagnostic par panel IgE.</li><li>Éviction et réintroduction encadrées selon mécanisme/gravité. Allaitement poursuivi ; éviction maternelle seulement si indiquée, avec conseil nutritionnel.</li><li>Si besoin de substitut : préparation adaptée, souvent hydrolysat poussé, parfois <span class=\"nc-pink_bg nc-bold\">acides aminés</span> selon sévérité/<span class=\"nc-red_bg\">échec</span>. Lait de chèvre/brebis et boissons végétales ordinaires ne sont pas des substituts appropriés du nourrisson.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://doi.org/10.1111/all.15902\" target=\"_blank\" rel=\"noopener noreferrer\">EAACI · diagnostic de l’allergie alimentaire, 2023</a></li><li><a href=\"https://eaaci.org/guidelines-position-papers/eaaci-guidelines-on-the-management-of-ige-mediated-food-allergy/\" target=\"_blank\" rel=\"noopener noreferrer\">EAACI · prise en charge de l’allergie alimentaire</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’algorithme de prise en charge diagnostique et thérapeutique de l’allergie alimentaire IgE-dépendante à l’arachide et aux fruits à coque","contenu":"<div class=\"notion-course\"><h4>Arachide et <span class=\"nc-pink nc-bold\">fruits à coque</span> : une démarche ciblée</h4><ol><li>Reconstituer la réaction : <span class=\"nc-red nc-bold\">aliment</span> et forme, quantité, délai, organes, cofacteurs, traitement et aliments déjà tolérés. Si anaphylaxie actuelle, traiter avant le bilan.</li><li>Prick et/ou IgE spécifiques orientés. Les composants Ara h 2, Cor a 14 ou Ana o 3 peuvent soutenir le diagnostic selon l’<span class=\"nc-red nc-bold\">aliment</span>. Aucun taux ne prédit à lui seul la gravité de la prochaine réaction.</li><li>Discordance/doute ou réévaluation de tolérance : <span class=\"nc-blue_bg\">test de provocation</span> orale en centre spécialisé si bénéfice attendu ; pas obligatoire après toute histoire convaincante.</li><li>Éviction individualisée des aliments réellement en cause, conseil diététique, trousse et plan écrit ; rechercher les <span class=\"nc-brown_bg\">allergies</span> associées selon l’histoire, sans bannir automatiquement toutes les légumineuses/<span class=\"nc-orange nc-bold\">fruits à coque</span>.</li><li><span class=\"nc-pink_bg\">Adrénaline auto-injectable</span> si risque d’anaphylaxie, avec apprentissage ; PAI pour l’enfant. Immunothérapie orale uniquement en centre expérimenté, avec risques et contraintes expliqués.</li></ol><div class=\"callout\"><p>Ara h 2 aide à distinguer une <span class=\"nc-red nc-bold\">sensibilisation</span> pertinente ; positif ne signifie pas « anaphylaxie certaine ». Un résultat négatif isolé ne permet pas une réintroduction à domicile après une réaction grave.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://doi.org/10.1111/all.15902\" target=\"_blank\" rel=\"noopener noreferrer\">EAACI · diagnostic de l’allergie alimentaire, 2023</a></li><li><a href=\"https://eaaci.org/guidelines-position-papers/eaaci-guidelines-on-the-management-of-ige-mediated-food-allergy/\" target=\"_blank\" rel=\"noopener noreferrer\">EAACI · prise en charge de l’allergie alimentaire</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’algorithme de prise en charge diagnostique et thérapeutique de l’allergie alimentaire aux allergènes croisant avec les pneumallergènes","contenu":"<div class=\"notion-course\"><h4><span class=\"nc-brown_bg\">Allergies</span> croisées : interpréter la clinique</h4><table><thead><tr><th>Association</th><th>Repère</th></tr></thead><tbody><tr><td>Bouleau–pomme</td><td>PR-10 : <span class=\"nc-red_bg\">syndrome oral</span> fréquent avec végétal cru, protéines souvent thermolabiles.</td></tr><tr><td>Acariens–<span class=\"nc-pink nc-bold\">crustacés</span></td><td>Tropomyosines : <span class=\"nc-red nc-bold\">sensibilisation</span> croisée <span class=\"nc-yellow_bg\">possible</span>, <span class=\"nc-red nc-bold\">allergie</span> clinique à démontrer.</td></tr><tr><td>Latex–fruits</td><td>Banane, avocat, kiwi… selon protéines communes.</td></tr><tr><td>Autres</td><td>Oiseau–œuf, chat–porc, <span class=\"nc-blue nc-bold\">cyprès</span>–pêche : histoire et bilan spécialisé.</td></tr></tbody></table><ul><li>Interroger aliments crus/cuits, portion, saison, organes et cofacteurs ; prick avec <span class=\"nc-red nc-bold\">aliment</span> natif et IgE moléculaires si nécessaires.</li><li>PR-10/profilines sont souvent associées à des <span class=\"nc-red nc-bold\">symptômes</span> locaux ; ne jamais promettre une bénignité absolue. LTP et autres protéines stables peuvent donner des réactions systémiques.</li><li>Éviction de la forme réellement responsable ; conserver les aliments/formes tolérés selon avis. Ne pas tester chez soi une forme cuite après une réaction sévère.</li><li>Trousse et adrénaline selon risque clinique, pas seulement selon le nom d’une molécule. Une immunothérapie <span class=\"nc-red nc-bold\">pollinique</span> n’est pas une garantie de guérison de l’<span class=\"nc-red_bg\">allergie alimentaire</span>.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://doi.org/10.1111/all.15902\" target=\"_blank\" rel=\"noopener noreferrer\">EAACI · diagnostic de l’allergie alimentaire, 2023</a></li><li><a href=\"https://eaaci.org/guidelines-position-papers/eaaci-guidelines-on-the-management-of-ige-mediated-food-allergy/\" target=\"_blank\" rel=\"noopener noreferrer\">EAACI · prise en charge de l’allergie alimentaire</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies aux venins d’hyménoptères","contenu":"<div class=\"notion-course\"><ol><li>Identifier si <span class=\"nc-yellow_bg\">possible</span> l’insecte, nombre de piqûres, délai, <span class=\"nc-red nc-bold\">symptômes</span> et gravité ; distinguer local, systémique allergique et toxicité d’envenimation.</li><li>Bilan spécialisé après réaction systémique : prick et/ou <span class=\"nc-blue_bg\">IDR</span> aux concentrations validées, IgE spécifiques ; composants moléculaires si double <span class=\"nc-red nc-bold\">sensibilisation</span> ou discordance.</li><li><span class=\"nc-pink nc-bold\">Tryptase</span> aiguë puis basale selon épisode ; rechercher maladie mastocytaire en cas de réaction sévère/arguments de terrain. Une <span class=\"nc-pink nc-bold\">tryptase</span> &gt; 20 ng/mL ne suffit pas à diagnostiquer une <span class=\"nc-red nc-bold\">mastocytose</span>, et une valeur normale ne l’exclut pas.</li><li>Tests initialement négatifs malgré histoire forte : réévaluer à distance avec l’allergologue. Pas de provocation par <span class=\"nc-red nc-bold\">piqûre</span> improvisée.</li><li>Décider prévention, auto-injecteurs et immunothérapie selon risque, clinique et <span class=\"nc-red nc-bold\">sensibilisation</span> pertinente. Prick et IDR ne sont pas opposés par une règle universelle « jamais de prick ». </li></ol></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://www.sfmu.org/upload/consensus/rfe_anaphylaxie_sfmu2016.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SFMU/SFA · anaphylaxie en urgence</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-11","rang":"A","rubrique":"Étiologies","titre":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","contenu":"<div class=\"notion-course\"><table><thead><tr><th>Milieu</th><th>Expositions</th></tr></thead><tbody><tr><td>Intérieur</td><td><span class=\"nc-yellow_bg\">Acariens</span>, animaux, <span class=\"nc-yellow_bg\">blattes</span>, <span class=\"nc-yellow_bg\">moisissures</span> ; <span class=\"nc-red nc-bold\">humidité</span> et <span class=\"nc-green_bg\">ventilation</span> modulent la charge.</td></tr><tr><td>Extérieur</td><td><span class=\"nc-green_bg\">Pollens d’arbres</span>, <span class=\"nc-brown_bg\">graminées</span>, herbacées ; <span class=\"nc-yellow_bg\">moisissures</span> dont Alternaria. Saisons variables selon région/climat.</td></tr><tr><td>Professionnel</td><td>Farines/enzymes, latex, persulfates, isocyanates, bois, désinfectants ; allergènes et <span class=\"nc-red nc-bold\">irritants</span> peuvent coexister.</td></tr></tbody></table><ul><li>Tabac, pollution et <span class=\"nc-red nc-bold\">irritants</span> aggravent les voies aériennes sans être tous des allergènes. Les virus déclenchent des exacerbations mais ne sont pas classés comme pneumallergènes usuels.</li><li>Expositions au foin moisi/protéines aviaires : penser aussi à pneumopathie d’<span class=\"nc-red nc-bold\">hypersensibilité</span>, de mécanisme différent de l’asthme IgE.</li><li>Mesures proportionnées : réparer <span class=\"nc-red nc-bold\">humidité</span>, ventiler, adapter <span class=\"nc-red nc-bold\">literie</span>/nettoyage si <span class=\"nc-red nc-bold\">allergie</span> pertinente, limiter <span class=\"nc-red nc-bold\">exposition</span> <span class=\"nc-red nc-bold\">pollinique</span>, agir au travail avec médecin du travail. Un CMEI peut aider.</li><li>Les associations entre biodiversité et <span class=\"nc-brown_bg nc-bold\">atopie</span> ne justifient pas de provoquer des infections ni de dégrader l’hygiène. Pas d’éviction alimentaire préventive non indiquée.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":4},{"id":"186-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","contenu":"<div class=\"notion-course\"><ul><li>Test sanguin multiallergénique : orientation qualitative vers une <span class=\"nc-red nc-bold\">sensibilisation</span> à un composant du mélange, notamment si suspicion respiratoire et accès limité aux <span class=\"nc-red\">tests cutanés</span>.</li><li>Positif : ne précise ni allergène responsable, ni <span class=\"nc-red nc-bold\">symptômes</span>, ni sévérité ; compléter par bilan ciblé si utile.</li><li>Négatif : n’exclut pas un allergène absent du panel, un mécanisme non IgE ou une forte suspicion clinique.</li><li>Si l’<span class=\"nc-red nc-bold\">aliment</span> suspect est connu, préférer l’enquête ciblée ; éviter les panels alimentaires larges sans indication et les évictions qui en découlent.</li><li>Ne pas prescrire IgE totales/IgG alimentaires comme dépistage de l’allergie IgE. Des indications spécialisées de ces analyses existent en dehors de cette question.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de réalisation et de prescription des tests cutanés en allergologie","contenu":"<div class=\"notion-course\"><table><thead><tr><th>Technique</th><th>Principe et lecture</th></tr></thead><tbody><tr><td>Prick</td><td>Microponction à travers extrait/<span class=\"nc-red nc-bold\">aliment</span> natif sur peau saine ; lecture vers 15–20 min. Papule <span class=\"nc-pink nc-bold\">≥ 3 mm</span> au-delà du témoin négatif, avec <span class=\"nc-pink nc-bold\">histamine</span> réactive.</td></tr><tr><td>IDR</td><td>Injection intradermique à concentration validée, surtout <span class=\"nc-pink nc-bold\">venins</span>/<span class=\"nc-pink nc-bold\">médicaments</span> ; lecture immédiate ou <span class=\"nc-red nc-bold\">retardée</span> selon indication spécialisée.</td></tr><tr><td>Patch</td><td>Application cutanée pour <span class=\"nc-red nc-bold\">hypersensibilité</span> <span class=\"nc-red nc-bold\">retardée</span>, notamment <span class=\"nc-pink nc-bold\">eczéma de contact</span> ; lectures à J2 puis J3–J4, parfois J7.</td></tr></tbody></table><ul><li>Choix guidé par l’histoire, le mécanisme et le risque. Les témoins/méthodes d’interprétation ne sont pas identiques pour les trois techniques.</li><li>Vérifier peau, dermographisme et <span class=\"nc-pink nc-bold\">médicaments</span> pouvant modifier la réponse. Arrêt des <span class=\"nc-red nc-bold\">antihistaminiques</span> selon molécule et protocole ; ne pas interrompre seul un traitement essentiel ou une biothérapie.</li><li>Prick : mesurer la papule, pas le seul <span class=\"nc-red_bg\">érythème</span> ; témoins non interprétables = prudence/alternative sanguine.</li><li>Surveillance médicale et moyens de traiter une réaction systémique ; durée adaptée au test/risque. Tests de <span class=\"nc-pink nc-bold\">venins</span>/<span class=\"nc-pink nc-bold\">médicaments</span> et toxidermies : cadre expert.</li><li>Un patch faiblement positif peut être allergique ; l’intensité ne sépare pas à elle seule irritation et <span class=\"nc-red nc-bold\">allergie</span>. Pas de patch alimentaire de dépistage en routine.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":4},{"id":"186-14","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","contenu":"<div class=\"notion-course\"><h4>Prévenir et savoir agir</h4><ul><li>Identifier précisément l’allergène et les aliments/formes à éviter ; lire les étiquettes et discuter les mentions de contamination croisée. Maintenir une alimentation suffisante avec diététicien si besoin.</li><li>Plan écrit adapté aux <span class=\"nc-red nc-bold\">symptômes</span>, traitement prescrit, contacts d’urgence et contexte ; former patient, entourage, école/collectivité. PAI élaboré avec famille et professionnels concernés, en partageant les informations nécessaires.</li><li>Auto-injecteurs d’adrénaline si antécédent ou risque d’anaphylaxie, y compris chez certains patients sans épisode antérieur. Choix de dose selon poids et dispositif ; vérifier disponibilité, péremption et démonstration.</li><li><span class=\"nc-red nc-bold\">Urticaire</span> isolée sans signe respiratoire/circulatoire : H1 et surveillance selon plan. Atteinte respiratoire/circulatoire ou combinaison compatible avec anaphylaxie : <span class=\"nc-pink nc-bold\">adrénaline IM</span> immédiate, appel 15/112 ; ne pas attendre le choc.</li><li>Injection dans la face antérolatérale de la cuisse ; répétition si persistance, généralement à 5–10 min selon plan/secours. Dose médicale de référence : 0,01 mg/kg, maximum 0,5 mg. Les stylos ont des doses fixes adaptées au poids, pas une dose adulte unique universelle.</li><li>Éviter lever/marche ; allonger si toléré, adapter en cas de dyspnée/vomissements. Surveillance hospitalière après anaphylaxie.</li><li>H1 et <span class=\"nc-red nc-bold\">corticoïdes</span> ne remplacent jamais l’adrénaline et ne préviennent pas de façon démontrée toute réaction biphasique. Adrénaline IV réservée aux équipes expertes dans les situations indiquées ; arrêt cardiaque = protocole de réanimation.</li></ul><p>Le grade de sévérité aide à décrire l’épisode, mais la décision urgente repose sur les critères cliniques d’anaphylaxie. Réévaluer asthme, cofacteurs, accès aux soins et compréhension du plan.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://www.sfmu.org/upload/consensus/rfe_anaphylaxie_sfmu2016.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SFMU/SFA · anaphylaxie en urgence</a></li><li><a href=\"https://doi.org/10.1111/all.15902\" target=\"_blank\" rel=\"noopener noreferrer\">EAACI · diagnostic de l’allergie alimentaire, 2023</a></li><li><a href=\"https://eaaci.org/guidelines-position-papers/eaaci-guidelines-on-the-management-of-ige-mediated-food-allergy/\" target=\"_blank\" rel=\"noopener noreferrer\">EAACI · prise en charge de l’allergie alimentaire</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":1},{"id":"186-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’une conjonctivite allergique","contenu":"<div class=\"notion-course\"><ul><li>Prurit oculaire, larmoiement clair et rougeur généralement bilatérale, parfois chémosis/œdème palpébral, avec contexte allergénique et <span class=\"nc-orange_bg\">rhinite</span>.</li><li>Le prurit est très évocateur mais non pathognomonique. La <span class=\"nc-orange_bg\">conjonctivite allergique</span> simple est habituellement indolore, sans baisse visuelle.</li><li>Douleur, baisse visuelle, photophobie marquée ou atteinte cornéenne : avis ophtalmologique rapide, sans attribuer automatiquement à une allergie.</li><li>Différentiels : infection, sécheresse, irritation, corps étranger et kératoconjonctivite sévère.</li><li>Bilan allergologique si utile à la prise en charge, notamment avant immunothérapie ; pas de provocation conjonctivale de routine.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d’une conjonctivite allergique","contenu":"<div class=\"notion-course\"><ol><li>Éviter le frottement, réduire l’<span class=\"nc-red nc-bold\">exposition</span> pertinente ; sérum physiologique, compresses fraîches et larmes adaptées.</li><li>Antihistaminique local et/ou stabilisateur mastocytaire ; H1 oral de deuxième génération si rhinoconjonctivite associée.</li><li>Si persistance ou signe d’alarme : réexaminer le diagnostic, avis ophtalmologique. Corticoïde oculaire seulement sous contrôle spécialisé (pression, cornée, infection).</li><li>Immunothérapie allergénique discutée par l’allergologue pour rhinoconjonctivite gênante liée à un allergène pertinent malgré prise en charge adaptée ; asthme contrôlé et produit indiqué.</li></ol><p>L’ITA peut réduire durablement <span class=\"nc-red nc-bold\">symptômes</span> et <span class=\"nc-pink nc-bold\">médicaments</span> ; ne pas promettre prévention/guérison systématique. Polysensibilisation <span class=\"nc-yellow_bg\">possible</span> si allergène pertinent identifié. Voie, âge, durée et contre-indications suivent le produit et l’évaluation spécialisée.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-17","rang":"A","rubrique":"Pédiatrie — Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-red_bg\">Allergie alimentaire</span> de <span class=\"nc-red_bg nc-bold\">l’enfant</span> : quelques pour cent, avec prédominance lait/<span class=\"nc-red nc-bold\">œuf</span> chez le plus jeune et importance de l’<span class=\"nc-green_bg\">arachide</span>/<span class=\"nc-green_bg\">fruits à coque</span> par la suite. Les classements exacts varient selon cohortes.</li><li>Tolérance plus fréquente pour lait/<span class=\"nc-red nc-bold\">œuf</span> ; <span class=\"nc-brown_bg\">allergies</span> <span class=\"nc-yellow_bg\">arachide</span>/<span class=\"nc-pink nc-bold\">fruits à coque</span> souvent persistantes, avec réévaluations individualisées. Aucun âge ne garantit la guérison.</li><li>Risque nutritionnel, anxiété, exclusion sociale et anaphylaxie : éducation et suivi de croissance essentiels.</li><li>SEIPA : vomissements retardés, <span class=\"nc-brown_bg\">pâleur</span>/<span class=\"nc-brown_bg\">léthargie</span>, parfois choc ; mécanisme principalement non IgE. Œsophagite à <span class=\"nc-green nc-bold\">éosinophiles</span> : dysphagie/blocage alimentaire, diagnostic spécialisé ; ne pas écrire « dyspnée alimentaire ».</li><li>La <span class=\"nc-red nc-bold\">marche atopique</span> décrit des trajectoires fréquentes, pas une succession obligatoire ni des âges fixes. Diversification et prévention suivent les recommandations pédiatriques, sans évictions improvisées.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/hypersensibilites-allergies\" target=\"_blank\" rel=\"noopener noreferrer\">CNPU · hypersensibilités et allergies</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-18","rang":"A","rubrique":"Pédiatrie — Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","contenu":"<div class=\"notion-course\"><ul><li>L’asthme concerne <span class=\"nc-yellow_bg\">environ</span> un enfant scolarisé sur dix en France ; tout asthme pédiatrique n’est pas allergique. La fréquence de la <span class=\"nc-orange_bg\">rhinite</span> varie beaucoup avec l’âge et les définitions.</li><li>Pneumallergènes : <span class=\"nc-red_bg\">acariens</span>, animaux, <span class=\"nc-yellow_bg\">moisissures</span> et <span class=\"nc-red_bg\">pollens</span> ; une <span class=\"nc-red nc-bold\">allergie</span> <span class=\"nc-red nc-bold\">pollinique</span> peut apparaître avant la puberté.</li><li>La <span class=\"nc-red nc-bold\">sensibilisation</span>, l’<span class=\"nc-red nc-bold\">allergie</span> clinique et l’asthme sont des mesures différentes ; ne pas additionner leurs prévalences.</li><li>Retentissement sur sommeil, scolarité, activité et famille ; formes graves possibles. Le chiffre d’<span class=\"nc-yellow_bg\">environ</span> 1 000 décès annuels du référentiel concerne l’asthme tous âges, pas la mortalité pédiatrique.</li><li>Terrain familial, tabac/pollution et expositions influencent le risque ; <span class=\"nc-red nc-bold\">effort</span> et virus peuvent déclencher des <span class=\"nc-red nc-bold\">symptômes</span> sans être des allergènes.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/hypersensibilites-allergies\" target=\"_blank\" rel=\"noopener noreferrer\">CNPU · hypersensibilités et allergies</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0},{"id":"186-19","rang":"A","rubrique":"Pédiatrie — Examens complémentaires","titre":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-red_bg\">Chez l’enfant</span> comme <span class=\"nc-red_bg\">l’adulte</span>, commencer par l’histoire ; prick possibles même chez le nourrisson avec techniques/interprétation adaptées. Pas d’âge minimal universel de 3 mois.</li><li>Si peau non testable, médicament gênant ou question ciblée : IgE spécifiques ; un mélange peut orienter dans certaines suspicions respiratoires.</li><li>Un panel combiné n’est pas un test universel de première intention devant <span class=\"nc-red nc-bold\">symptômes</span> vagues. Il implique une prise de sang et ne diagnostique ni SEIPA ni toute allergie non IgE.</li><li>Éviter les panels alimentaires sans hypothèse et les régimes d’éviction sur positivité isolée ; confirmer la pertinence et prévoir suivi nutritionnel.</li><li>TPO en centre spécialisé si doute ou évaluation de tolérance, après appréciation du risque ; jamais de provocation non encadrée après réaction grave.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hypersensibilités (186)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941814fb9ebe0008ab21d80?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Allergies alimentaires</a></li><li><a href=\"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx\" target=\"_blank\" rel=\"noopener noreferrer\">CEP · item 186 · 9e édition 2026</a></li><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/hypersensibilites-allergies\" target=\"_blank\" rel=\"noopener noreferrer\">CNPU · hypersensibilités et allergies</a></li></ul><p>Sensibilisation distinguée de l’allergie clinique ; risques et examens ciblés, sans éviction ni test de provocation automatique.</p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Sensibilisation ≠ allergie","contenu":"<div class=\"notion-course\"><p>Confronter tout test à l’<span class=\"nc-red nc-bold\">exposition</span> et aux <span class=\"nc-red nc-bold\">symptômes</span>.</p></div>"},{"type":"piege","titre":"Adrénaline sans retard","contenu":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">L’anaphylaxie</span> ne nécessite pas d’attendre le choc ou un grade élevé.</p></div>"},{"type":"piege","titre":"Éviction ciblée","contenu":"<div class=\"notion-course\"><p>Préserver les aliments tolérés et l’équilibre nutritionnel.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Histoire → tests orientés → interprétation clinique ; provocation spécialisée si nécessaire.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Traiter l’urgence puis organiser prévention, plan écrit et suivi.</li><li>L’immunothérapie exige une indication et une surveillance spécialisées.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://cep.splf.fr/wp-content/uploads/2026/09/Item_186-hypersensibilite-2026.docx","label":"CEP · item 186 · 9e édition 2026 ↗"},{"href":"https://www.sfmu.org/upload/consensus/rfe_anaphylaxie_sfmu2016.pdf","label":"SFMU/SFA · anaphylaxie en urgence ↗"},{"href":"https://doi.org/10.1111/all.15902","label":"EAACI · diagnostic de l’allergie alimentaire, 2023 ↗"},{"href":"https://eaaci.org/guidelines-position-papers/eaaci-guidelines-on-the-management-of-ige-mediated-food-allergy/","label":"EAACI · prise en charge de l’allergie alimentaire ↗"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/hypersensibilites-allergies","label":"CNPU · hypersensibilités et allergies ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Atteinte respiratoire/circulatoire ou réaction systémique compatible ?","detail":"<ul><li>Dater l’exposition, les signes et les cofacteurs ; la peau peut être normale.</li></ul>","branches":[{"label":"Anaphylaxie possible","to":"adrenaline"},{"label":"Réaction non grave","to":"enquete"}]},{"id":"adrenaline","kind":"urgent","label":"Adrénaline IM et appel aux secours","detail":"<ul><li>Face antérolatérale de cuisse : 0,01 mg/kg, maximum 0,5 mg ; répéter selon évolution/protocole.</li><li>Position adaptée, oxygène/remplissage si indication ; H1/corticoïdes ne remplacent pas l’adrénaline.</li></ul>","branches":[{"label":"Après stabilisation","to":"enquete"}]},{"id":"enquete","kind":"decision","label":"Exposition cohérente et mécanisme probable ?","detail":"<ul><li>Venin, aliment, médicament ; conserver chronologie et documents, rechercher cofacteurs.</li><li>Tests dirigés : une sensibilisation ne suffit pas à diagnostiquer une allergie.</li></ul>","branches":[{"label":"Venin","to":"venin"},{"label":"Aliment","to":"aliment"},{"label":"Médicament / autre","to":"autre"}]},{"id":"venin","kind":"finish","label":"Bilan spécialisé et prévention","detail":"<ul><li>Type de réaction, insecte probable, tests et tryptase selon indication ; immunothérapie au venin si indiquée.</li></ul>","branches":[]},{"id":"aliment","kind":"finish","label":"Plan d’urgence et bilan ciblé","detail":"<ul><li>Identifier le véritable aliment responsable ; auto-injecteur et éducation selon risque.</li></ul>","branches":[]},{"id":"autre","kind":"finish","label":"Éviter les étiquettes non démontrées","detail":"<ul><li>Documenter précisément le produit et la réaction ; exploration spécialisée selon mécanisme et gravité.</li></ul>","branches":[]}]},"cards":[{"i":"1b0cf7c17357","n":186,"o":"186-11","u":"Étiologies","t":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","q":"Quels sont les autres allergènes importants et les facteurs environnementaux modulant le risque allergique ?","a":"<div class=\"notion-course\"><ul><li>Allergènes : <span class=\"nc-pink nc-bold\">venins</span>, <span class=\"nc-pink nc-bold\">médicaments</span>, latex et molécules de contact selon le mécanisme.</li><li>Tabac et pollution peuvent aggraver le risque respiratoire/allergique.</li><li>Associations entre environnement microbien, milieu rural et <span class=\"nc-red nc-bold\">allergie</span> : elles ne justifient ni <span class=\"nc-red nc-bold\">exposition</span> intentionnelle aux infections ni recommandation de crèche pour prévenir une <span class=\"nc-red nc-bold\">allergie</span>.</li></ul></div>"},{"i":"70af0f5f4401","n":186,"o":"186-11","u":"Étiologies","t":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","q":"Quels sont les principaux allergènes professionnels et les métiers à risque d'asthme professionnel ?","a":"<div class=\"notion-course\"><ul><li>Farines/enzymes (boulangerie), latex/désinfectants (santé), persulfates (coiffure), isocyanates (peinture), bois/colles et produits de nettoyage.</li><li>Foin moisi/protéines aviaires peuvent aussi provoquer une pneumopathie d’<span class=\"nc-red nc-bold\">hypersensibilité</span> : mécanisme distinct de l’asthme IgE.</li></ul></div>"},{"i":"8c0fa21b9ba2","n":186,"o":"186-11","u":"Étiologies","t":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","q":"Quelles sont les principales familles de pollens responsables d'allergies saisonnières et leurs périodes d'émission habituelles ?","a":"<div class=\"notion-course\"><ul><li>Arbres, <span class=\"nc-brown_bg\">graminées</span> et herbacées ; calendrier dépend de la région et du climat.</li><li><span class=\"nc-brown_bg\">Graminées</span> surtout fin de printemps/été ; arbres parfois dès l’hiver, <span class=\"nc-blue nc-bold\">armoise</span>/<span class=\"nc-blue nc-bold\">ambroisie</span> surtout été et fin de saison. Consulter les données locales.</li></ul></div>"},{"i":"be4872aba63d","n":186,"o":"186-11","u":"Étiologies","t":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","q":"Quels sont les principaux pneumallergènes domestiques perannuels et leurs conditions de prolifération ?","a":"<div class=\"notion-course\">Les principaux pneumallergènes domestiques perannuels sont :\n<ul>\n  <li>Les <strong><span class=\"nc-yellow_bg\">acariens</span></strong> (<i>Dermatophagoides pteronyssinus</i>, <i>D. farinae</i>) : on les trouve dans les <span class=\"nc-red nc-bold\">poussières de maison</span>, la <span class=\"nc-red nc-bold\">literie</span>, les <span class=\"nc-red nc-bold\">tapis</span>, les <span class=\"nc-red nc-bold\">moquettes</span>, les peluches et les canapés. Ils prolifèrent à une température de <strong>20–25 °C</strong> et une forte <strong><span class=\"nc-red nc-bold\">humidité</span></strong>.</li>\n  <li>Les <strong><span class=\"nc-yellow_bg\">phanères d'animaux</span></strong> (chien, chat, rongeurs) : les squames, la salive et l'urine en sont la source. Les allergènes de chat peuvent persister plusieurs mois après le départ de l'animal.</li>\n  <li>Les <strong><span class=\"nc-yellow_bg\">blattes</span></strong> (cafards) : elles sont présentes dans les cuisines, salles de bain et lieux aux conditions d'hygiène défavorables.</li>\n  <li>Les <strong><span class=\"nc-yellow_bg\">moisissures</span> intérieures</strong> (<i>Aspergillus</i>, <i>Penicillium</i>) : elles se développent dans les pièces humides (salle de bain, cuisine, caves). Une autre moisissure, <i>Alternaria</i>, est une moisissure d'extérieur marquant une gravité asthmatique <span class=\"nc-red_bg\">chez l'enfant</span>.</li>\n</ul></div>"},{"i":"0714d5d2be03","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Quels sont les différents composants de la trousse d'urgence pour une allergie alimentaire, et quand l'adrénaline auto-injectable est-elle indiquée ?","a":"<div class=\"notion-course\"><ul><li>Plan écrit, <span class=\"nc-pink_bg\">adrénaline auto-injectable</span> si risque d’anaphylaxie, H1 pour <span class=\"nc-red nc-bold\">symptômes</span> isolés et bronchodilatateur si indiqué.</li><li>Les <span class=\"nc-red nc-bold\">corticoïdes</span> ne sont pas un traitement vital de <span class=\"nc-red nc-bold\">l’anaphylaxie</span> et ne doivent pas retarder l’adrénaline.</li></ul></div>"},{"i":"1d21f2118360","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Dans quelles situations discuter ou prescrire des auto-injecteurs d’adrénaline ?","a":"<div class=\"notion-course\"><ul><li>Antécédent d’anaphylaxie ou risque significatif : <span class=\"nc-red_bg\">allergie alimentaire</span> à risque, asthme associé mal contrôlé, certains profils <span class=\"nc-pink nc-bold\">venins</span>/mastocytaires.</li><li>Décision clinique individualisée avec éducation ; une absence d’<span class=\"nc-red_bg\">anaphylaxie antérieure</span> n’exclut pas l’indication.</li></ul></div>"},{"i":"2d84bec2cac2","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Qu'est-ce que le Projet d'Accueil Individualisé (PAI) dans le contexte de l'allergie alimentaire chez l'enfant ?","a":"<div class=\"notion-course\"><ul><li>Document personnalisé avec famille et professionnels pour l’accueil en collectivité : aliments concernés, <span class=\"nc-pink nc-bold\">médicaments</span> accessibles, conduite à tenir et responsables.</li><li>Former les intervenants et partager uniquement les informations nécessaires.</li></ul></div>"},{"i":"2ea019abd28d","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Quelle est la posologie et le mode d'administration de l'adrénaline auto-injectable, et quelles précautions doivent être prises après son administration ?","a":"<div class=\"notion-course\"><ul><li>IM dans la face antérolatérale de la cuisse ; dose du stylo adaptée au poids et au dispositif prescrit.</li><li>Appeler le 15/112, éviter lever/marche et adapter la position ; répéter si persistance selon plan, généralement à 5–10 min.</li><li>Dose médicale de référence : 0,01 mg/kg, max 0,5 mg ; ne pas confondre dose fixe du stylo et dose calculée.</li></ul></div>"},{"i":"b354d6cc6f26","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Faut-il attendre un grade ou un choc pour injecter l’adrénaline dans l’anaphylaxie ?","a":"<div class=\"notion-course\"><ul><li>Non. La décision repose sur une atteinte respiratoire/circulatoire ou une combinaison de <span class=\"nc-red nc-bold\">symptômes</span> compatible ; les signes <span class=\"nc-red\">cutanés</span> peuvent manquer.</li><li><span class=\"nc-pink nc-bold\">Adrénaline IM</span> immédiate et appel des secours. H1/<span class=\"nc-red nc-bold\">corticoïdes</span> ne la remplacent pas. Arrêt cardiaque : réanimation selon protocole.</li></ul></div>"},{"i":"b7a082a7465f","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Quels sont les objectifs de l'éducation thérapeutique dans la prise en charge de l'allergie alimentaire ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">éducation thérapeutique</span> dans l'<span class=\"nc-red_bg\">allergie alimentaire</span> vise principalement deux objectifs :</p><ul><li>Prévenir l'<strong><span class=\"nc-red nc-bold\">exposition</span> accidentelle</strong> à l'allergène (éviction, lecture d'étiquettes).</li><li>Savoir <strong>réagir en urgence</strong> en cas de réaction (plan d'action, trousse d'urgence, <span class=\"nc-pink_bg\">adrénaline auto-injectable</span>).</li></ul></div>"},{"i":"34826340a98a","n":186,"o":"186-15","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une conjonctivite allergique","q":"Quels sont les signes cliniques cardinaux et fortement évocateurs d'une conjonctivite allergique ?","a":"<div class=\"notion-course\"><ul><li>Prurit, larmoiement clair et rougeur bilatérale, parfois chémosis, contexte allergénique.</li><li>Prurit non pathognomonique ; douleur, photophobie importante ou baisse visuelle = rechercher une atteinte plus grave.</li></ul></div>"},{"i":"bc45f7007bcb","n":186,"o":"186-15","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une conjonctivite allergique","q":"Quelle est la démarche diagnostique essentielle devant une suspicion de conjonctivite allergique ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue nc-bold\">Interrogatoire</span> et examen, rechercher <span class=\"nc-orange_bg\">rhinite</span>/<span class=\"nc-red nc-bold\">exposition</span>, douleur, vision et atteinte cornéenne.</li><li>Bilan allergologique orienté si utile, notamment avant ITA ; pas de tests obligatoires dans toute conjonctivite simple.</li></ul></div>"},{"i":"d760cf7c43e1","n":186,"o":"186-15","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une conjonctivite allergique","q":"Quelle est la définition et la physiopathologie principale de la conjonctivite allergique ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-orange_bg\">conjonctivite allergique</span> est l'expression oculaire d'une <strong><span class=\"nc-red nc-bold\">hypersensibilité</span> immédiate de Type I (IgE-médiée)</strong>. Elle est le plus souvent bilatérale et associée à une <span class=\"nc-orange_bg\">rhinite</span> allergique sur un <span class=\"nc-orange nc-bold\">terrain atopique</span>.</p></div>"},{"i":"fb21158003f6","n":186,"o":"186-15","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une conjonctivite allergique","q":"Quels sont les principaux diagnostics différentiels à éliminer devant une conjonctivite allergique ?","a":"<div class=\"notion-course\"><ul><li>La <strong>conjonctivite infectieuse bactérienne</strong>, caractérisée par des <strong>sécrétions purulentes</strong> et souvent unilatérale.</li><li>La <strong>conjonctivite virale</strong>, associée à une <strong>adénopathie pré-auriculaire</strong> et un contexte épidémique.</li><li>La <strong>kérato-conjonctivite vernale</strong>, spécifique à <span class=\"nc-red_bg nc-bold\">l'enfant</span> (garçon), avec <strong>papilles géantes</strong> et <strong>atteinte cornéenne marquée</strong>.</li><li>Le <strong>syndrome sec</strong>, avec une sensation de brûlure plutôt que de prurit, et un <span class=\"nc-yellow_bg\">test de</span> Schirmer pathologique.</li><li>La <strong>conjonctivite irritative</strong>, liée à un contact chimique ou des polluants.</li></ul></div>"},{"i":"2e4722be7b65","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Dans quelles situations les corticoïdes locaux oculaires sont-ils indiqués pour une conjonctivite allergique et quelles précautions doivent être prises ?","a":"<div class=\"notion-course\"><p>Les collyres <span class=\"nc-red nc-bold\">corticoïdes</span> ne sont prescrits qu'en cas de <strong><span class=\"nc-red nc-bold\">certitude</span> diagnostique</strong> et <strong>après échec des traitements précédents</strong>.</p><p>Un <strong>avis ophtalmologique est obligatoire</strong> en raison des risques de <strong>glaucome cortisonique</strong>, de <strong>cataracte</strong> et d'<strong>infection oculaire</strong>.</p></div>"},{"i":"35192dd7798e","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Quels sont les traitements symptomatiques médicamenteux de première et deuxième intention pour la conjonctivite allergique ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-red nc-bold\">Antihistaminiques</span> locaux</strong> (collyres) : <strong>lévocabastine</strong>, <strong>olopatadine</strong> (double action antiH1 + stabilisateur mastocytaire), <strong>azélastine</strong>. Ils sont en première intention pour les formes isolées.</li><li><strong>Cromones locales</strong> (collyres) : <strong>cromoglycate de sodium</strong>. Ce sont des stabilisateurs mastocytaires, utiles en prévention avant <span class=\"nc-red nc-bold\">exposition</span> saisonnière.</li><li><strong><span class=\"nc-red nc-bold\">Antihistaminiques</span> oraux</strong> : <strong>antiH1 de 2<sup>e</sup> génération</strong> (cétirizine, loratadine, etc.), indiqués en cas de <strong>rhino-conjonctivite</strong> pour une action systémique.</li></ul></div>"},{"i":"638617deb6a8","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Quels sont les trois niveaux de traitement de la conjonctivite allergique mentionnés dans la stratégie thérapeutique ?","a":"<div class=\"notion-course\"><p>Le traitement de la <span class=\"nc-orange_bg\">conjonctivite allergique</span> repose sur trois niveaux :</p><ul><li>Niveau 1 : <strong>éviction allergénique</strong> et <strong>lavage oculaire</strong>.</li><li>Niveau 2 : <strong>Traitement symptomatique</strong> (<span class=\"nc-red nc-bold\">antihistaminiques</span> locaux ou oraux, cromones).</li><li>Niveau 3 : <strong>Traitement étiologique</strong> par immunothérapie allergénique (ITA).</li></ul></div>"},{"i":"e3ae4c5404c5","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Quand l'immunothérapie allergénique (ITA) est-elle indiquée pour une rhino-conjonctivite allergique et quels en sont les bénéfices ?","a":"<div class=\"notion-course\"><ul><li>Rhinoconjonctivite gênante avec allergène pertinent malgré prise en charge adaptée ; décision spécialisée selon produit et terrain.</li><li>Réduit <span class=\"nc-red nc-bold\">symptômes</span> et recours médicamenteux ; bénéfices préventifs possibles dans certaines populations, sans garantie individuelle.</li></ul></div>"},{"i":"fc424f77873c","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Quelles sont les mesures d'éviction allergénique spécifiques en cas de conjonctivite allergique et les modalités du lavage oculaire ?","a":"<div class=\"notion-course\"><ul><li><strong>Acariens</strong> : <span class=\"nc-pink_bg nc-bold\">housses anti-acariens</span>, lavage des draps à <strong><span class=\"nc-pink nc-bold\">≥ 60 °C</span></strong>, <span class=\"nc-pink_bg nc-bold\">aspiration</span> HEPA.</li><li><strong><span class=\"nc-red_bg\">Pollens</span></strong> : sécher le linge à l'intérieur, fermer les fenêtres en période de pic <span class=\"nc-red nc-bold\">pollinique</span>.</li><li><strong>Animaux</strong> : ne pas les laisser accéder à la chambre, lavage régulier.</li><li>Le <strong>lavage oculaire</strong> se fait au <strong>sérum physiologique</strong>, plusieurs fois par jour pendant la phase symptomatique pour éliminer mécaniquement l'allergène et les <span class=\"nc-pink_bg\">médiateurs</span> locaux.</li></ul></div>"},{"i":"088457ade197","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Quels sont les principaux allergènes alimentaires pédiatriques classés par tranche d'âge ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">Lait de vache</span> et <span class=\"nc-red nc-bold\">œuf</span> importants chez le nourrisson ; <span class=\"nc-yellow_bg\">arachide</span>/<span class=\"nc-pink nc-bold\">fruits à coque</span>, puis autres aliments selon âge et habitudes.</li><li>Pas de classement universel à un anniversaire donné ; l’anamnèse guide le bilan.</li></ul></div>"},{"i":"126d10768bf2","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Quelle est la prévalence de l'allergie alimentaire pédiatrique en France et à quel âge atteint-elle son pic ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red_bg\">allergie alimentaire</span> pédiatrique concerne <strong>5 à 7 %</strong> des enfants français. Le pic de prévalence est observé entre <strong>6 et 10 ans</strong>, atteignant <strong>7 %</strong>.</p></div>"},{"i":"21f86a789203","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Quels allergènes sont associés à une allergie alimentaire durable et lesquels sont majoritairement transitoires chez l'enfant ?","a":"<div class=\"notion-course\"><ul><li>Tolérance acquise plus fréquente avec lait et <span class=\"nc-red nc-bold\">œuf</span> ; <span class=\"nc-yellow_bg\">arachide</span>/<span class=\"nc-pink nc-bold\">fruits à coque</span>, poissons/<span class=\"nc-pink nc-bold\">crustacés</span> plus souvent persistants.</li><li>Évolution variable : ne pas promettre une guérison avant un âge fixe, réévaluer en spécialité.</li></ul></div>"},{"i":"a06a5125a6fd","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Quels aliments sont particulièrement impliqués dans les anaphylaxies alimentaires sévères ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">Arachide</span> et <span class=\"nc-pink nc-bold\">fruits à coque</span> occupent une place importante ; lait et autres aliments peuvent aussi causer des réactions graves.</li><li>La gravité individuelle ne se déduit pas d’un classement de mortalité.</li></ul></div>"},{"i":"cada2c1561c2","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Qu'est-ce que la \"marche atopique\" et quelles sont les étapes chronologiques des manifestations observées ?","a":"<div class=\"notion-course\"><ul><li>Association de trajectoires atopiques : <span class=\"nc-orange nc-bold\">eczéma</span>, <span class=\"nc-red_bg\">allergie alimentaire</span>, asthme et rhinoconjonctivite.</li><li>Ni ordre obligatoire, ni âges fixes, ni prédiction certaine pour un enfant.</li></ul></div>"},{"i":"35b23e4a290b","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Quels sont les facteurs de risque spécifiques de l'allergie respiratoire chez l'enfant ?","a":"<div class=\"notion-course\"><ul><li>Terrain familial, sensibilisations pertinentes et environnement (tabac, pollution, expositions).</li><li>Virus et exercice peuvent déclencher des <span class=\"nc-red nc-bold\">symptômes</span> ; l’exercice n’est pas en lui-même un allergène et doit être encouragé avec contrôle adapté.</li></ul></div>"},{"i":"4d10d3173788","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Quel est l'impact de l'asthme sur la mortalité et la morbidité pédiatriques en France ?","a":"<div class=\"notion-course\"><ul><li>Retentissement scolaire, sommeil, activité, qualité de vie et recours aux urgences ; décès pédiatriques rares mais possibles.</li><li>Le chiffre de l’ordre de 1 000 décès/an en France concerne tous les âges, pas les enfants seuls.</li></ul></div>"},{"i":"8faa8e3b986f","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Qu'est-ce que la marche atopique et quelles sont ses étapes dans l'allergie respiratoire chez l'enfant ?","a":"<div class=\"notion-course\"><ul><li>La <span class=\"nc-yellow_bg\">marche atopique</span> décrit des trajectoires possibles d’<span class=\"nc-orange nc-bold\">eczéma</span>/<span class=\"nc-orange_bg\">allergies alimentaires</span> vers asthme/<span class=\"nc-orange_bg\">rhinite</span>.</li><li>Tous les enfants ne suivent pas cette succession ; allergie <span class=\"nc-red nc-bold\">pollinique</span> <span class=\"nc-yellow_bg\">possible</span> avant la puberté.</li></ul></div>"},{"i":"b7b9e72f2a03","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Quels sont les principaux allergènes respiratoires pédiatriques et leurs spécificités ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">Acariens</span>, animaux, <span class=\"nc-yellow_bg\">moisissures</span> et <span class=\"nc-red_bg\">pollens</span> ; les <span class=\"nc-brown_bg\">allergies</span> polliniques ne sont pas réservées à l’après-puberté.</li><li>Les virus déclenchent des exacerbations mais ne sont pas des pneumallergènes usuels.</li></ul></div>"},{"i":"b9fc38619074","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Quelle est la prévalence de l'allergie respiratoire infantile et sa tendance évolutive ?","a":"<div class=\"notion-course\"><ul><li>L’asthme touche <span class=\"nc-yellow_bg\">environ</span> 10 % des enfants scolarisés ; seule une partie est allergique.</li><li><span class=\"nc-orange_bg\">Rhinite</span> et <span class=\"nc-red nc-bold\">sensibilisation</span> ont des fréquences distinctes, variables avec âge et définition ; éviter un pourcentage unique pour toute l’enfance.</li></ul></div>"},{"i":"38af3272b8f2","n":186,"o":"186-19","u":"Pédiatrie — Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Dans quel contexte pédiatrique les tests multi-allergéniques IgE (Phadiatop, Trophatop, Phadiatop Infant) sont-ils particulièrement indiqués ?","a":"<div class=\"notion-course\"><p>Ces tests sont particulièrement utiles en pédiatrie lorsque le prick-test est :</p><ul><li>Limité techniquement (chez le <strong>très jeune enfant</strong>).</li><li>Contre-indiqué (en cas d'<strong><span class=\"nc-orange nc-bold\">eczéma</span> sévère diffus</strong>, de <strong>dermographisme</strong>).</li><li>Non interprétable (si le patient prend des <strong><span class=\"nc-red nc-bold\">antihistaminiques</span> non sevrables</strong>).</li></ul></div>"},{"i":"532c3228132b","n":186,"o":"186-19","u":"Pédiatrie — Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Quels sont les examens complémentaires à ne PAS prescrire pour le diagnostic d'allergie chez l'enfant ?","a":"<div class=\"notion-course\"><ul><li>IgE totales, <span class=\"nc-green nc-bold\">éosinophiles</span> et IgG alimentaires ne prouvent <span class=\"nc-red nc-bold\">pas une allergie</span> IgE et ne sont pas un dépistage de routine.</li><li>Ces analyses peuvent avoir d’autres indications spécialisées ; éviter « toujours inutiles/non remboursées ». </li></ul></div>"},{"i":"6981444fac87","n":186,"o":"186-19","u":"Pédiatrie — Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Quelle est la hiérarchie des examens complémentaires pour le diagnostic d'allergie en pédiatrie ?","a":"<div class=\"notion-course\"><ul><li>Histoire/examen puis prick ou IgE spécifiques ciblés selon faisabilité et hypothèse.</li><li>Mélange multiallergénique dans certaines indications d’orientation ; pas une étape obligatoire. TPO spécialisé si doute/tolérance à réévaluer.</li></ul></div>"},{"i":"7255ce800309","n":186,"o":"186-19","u":"Pédiatrie — Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Quel est l'intérêt du Phadiatop Infant spécifiquement en pédiatrie ?","a":"<div class=\"notion-course\"><ul><li>Panel combiné pouvant orienter une <span class=\"nc-red nc-bold\">sensibilisation</span> dans une situation sélectionnée.</li><li>Ce n’est ni un dépistage universel des <span class=\"nc-red nc-bold\">symptômes</span> vagues, ni un <span class=\"nc-yellow_bg\">test de</span> SEIPA ; résultat positif à confronter à la clinique, sans éviction automatique.</li></ul></div>"},{"i":"6aac3e9c9606","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Quand réalise-t-on des tests cutanés (prick-tests) dans le diagnostic d'une allergie respiratoire et quels sont les critères positifs ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-blue_bg\">tests cutanés (</span><strong><span class=\"nc-yellow_bg\">prick-tests</span></strong>) sont réalisés en <strong>1<sup>ère</sup> intention</strong> dans le diagnostic d'une <span class=\"nc-red nc-bold\">allergie</span> respiratoire, après l'anamnèse. Leur objectif est d'objectiver une <strong><span class=\"nc-red nc-bold\">sensibilisation</span> IgE-médiée</strong>. Les critères positifs sont une <strong>papule <span class=\"nc-pink nc-bold\">≥ 3 mm</span></strong> par rapport au témoin négatif, avec un témoin positif (<span class=\"nc-pink nc-bold\">histamine</span>) réactif.</p></div>"},{"i":"7ae0b0e5d930","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Dans quelles situations les tests biologiques (IgE spécifiques) sont-ils indiqués pour le diagnostic d'une allergie respiratoire et quel est leur critère positif ?","a":"<div class=\"notion-course\"><ul><li>Si prick impossibles, discordants ou besoin d’un <span class=\"nc-blue_bg nc-bold\">complément</span> ciblé.</li><li>Le seuil dépend du test ; une valeur détectable, dont le repère classique 0,35 kUA/L, indique une <span class=\"nc-red nc-bold\">sensibilisation</span> et ne prouve ni <span class=\"nc-red nc-bold\">allergie</span> ni gravité.</li></ul></div>"},{"i":"b7c958afb93e","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Quels examens ne doivent PAS être prescrits dans le diagnostic d'une allergie respiratoire et pourquoi ?","a":"<div class=\"notion-course\"><ul><li>IgE totales, <span class=\"nc-green nc-bold\">éosinophiles</span> et IgG ne sont pas des tests de dépistage prouvant une allergie respiratoire IgE.</li><li><span class=\"nc-pink nc-bold\">Tryptase</span> : anaphylaxie et terrain mastocytaire selon indication ; autres dosages utiles dans des maladies <span class=\"nc-orange_bg\">spécifiques</span>, sans remplacer anamnèse/prick/IgE ciblées.</li></ul></div>"},{"i":"f05a28987669","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Quand est-ce qu'un test de provocation est réalisé dans le diagnostic d'une allergie respiratoire et où doit-il être effectué ?","a":"<div class=\"notion-course\"><p>Un <strong><span class=\"nc-blue_bg\">test de provocation</span></strong> est réalisé <strong>rarement</strong>, uniquement pour un diagnostic de <span class=\"nc-red nc-bold\">certitude</span> lorsque le bilan de première intention (anamnèse, <span class=\"nc-yellow_bg\">prick-tests</span>, IgE <span class=\"nc-blue nc-bold\">spécifiques</span>) est <strong>insuffisant</strong> et qu'il existe un <strong>impact thérapeutique</strong>. Ces tests (nasaux ou bronchiques) doivent être effectués <strong>exclusivement en milieu spécialisé hospitalier</strong>.</p></div>"},{"i":"f87d5fab919a","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Quelle est la première étape du diagnostic d'une allergie respiratoire et quels sont les critères positifs ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue nc-bold\">Interrogatoire</span> : <span class=\"nc-red nc-bold\">symptômes</span>, chronologie, lieu, saison, <span class=\"nc-red nc-bold\">exposition</span>, répétition et cofacteurs.</li><li>Le délai est souvent rapide mais pas toujours &lt; 1 h ; dose et cofacteurs modulent la réaction.</li></ul></div>"},{"i":"13e6ad0d26eb","n":186,"o":"186-7","u":"Diagnostic positif","t":"Connaître les principaux allergènes de l’allergie alimentaire IgE-dépendante","q":"Quels sont les principaux allergènes alimentaires IgE-dépendants chez l'adulte ?","a":"<div class=\"notion-course\"><p>Chez <span class=\"nc-red_bg\">l'adulte</span>, les principaux allergènes alimentaires IgE-dépendants sont :</p><ul><li>Les <strong><span class=\"nc-pink nc-bold\">fruits à coque</span></strong> (pistache, noix de cajou, noisette, noix, amande)</li><li>Les <strong>fruits frais</strong> (<span class=\"nc-pink nc-bold\">pomme</span>, poire, prune, pêche, abricot, <span class=\"nc-pink nc-bold\">kiwi</span>)</li><li>Les <strong><span class=\"nc-pink nc-bold\">crustacés</span></strong></li></ul></div>"},{"i":"3f7793a451c4","n":186,"o":"186-7","u":"Diagnostic positif","t":"Connaître les principaux allergènes de l’allergie alimentaire IgE-dépendante","q":"Quelle place occupe l’arachide parmi les allergies alimentaires de l’enfant ?","a":"<div class=\"notion-course\"><ul><li>Allergène important, souvent persistant et impliqué dans des réactions sévères.</li><li>Le classement dépend de l’âge et des populations ; aucun anniversaire n’en fait universellement le premier allergène.</li></ul></div>"},{"i":"4d213efa3179","n":186,"o":"186-7","u":"Diagnostic positif","t":"Connaître les principaux allergènes de l’allergie alimentaire IgE-dépendante","q":"Quels sont les principaux allergènes alimentaires IgE-dépendants chez l'enfant de moins de 1 an ?","a":"<div class=\"notion-course\"><p>Avant l'âge de 1 an, les principaux allergènes alimentaires IgE-dépendants <span class=\"nc-red_bg\">chez l'enfant</span> sont le <strong><span class=\"nc-red nc-bold\">lait de vache</span></strong> et l'<strong><span class=\"nc-red nc-bold\">œuf</span></strong>.</p></div>"},{"i":"79dfd6b988c1","n":186,"o":"186-1","u":"Physiopathologie","t":"Connaître la physiopathologie des réactions d’hypersensibilité : allergique et non allergique","q":"Une sensibilisation prouve-t-elle une allergie clinique ?","a":"<div class=\"notion-course\"><ul><li>Non. Il faut une histoire compatible et une relation entre <span class=\"nc-red nc-bold\">exposition</span> et <span class=\"nc-red nc-bold\">symptômes</span>.</li></ul></div>"},{"i":"20c9693e06e1","n":186,"o":"186-2","u":"Epidémiologie","t":"Connaître les grandes tendances épidémiologiques des allergies aux venins d’hyménoptères : prévalence, mortalité","q":"Plusieurs piqûres d’hyménoptères avec réaction générale prouvent-elles une allergie ?","a":"<div class=\"notion-course\"><ul><li>Non. Une envenimation toxique dose-dépendante est aussi <span class=\"nc-yellow_bg\">possible</span> ; évaluer les deux mécanismes.</li></ul></div>"},{"i":"fd9a634d3cc6","n":186,"o":"186-3","u":"Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"L’allergie au lait guérit-elle toujours avant 3 ans ?","a":"<div class=\"notion-course\"><ul><li>Non. La tolérance est fréquente mais son délai varie ; réévaluation spécialisée.</li></ul></div>"},{"i":"b164c3bb0be7","n":186,"o":"186-4","u":"Epidémiologie","t":"Connaître les grandes tendances épidémiologiques des hypersensibilités allergiques et non allergiques médicamenteuses : prévalence, morbidité, mortalité","q":"Une réaction à un produit de contraste est-elle une allergie à l’iode ?","a":"<div class=\"notion-course\"><ul><li>Non. Décrire le produit et le mécanisme suspecté ; réaction allergique ou non allergique <span class=\"nc-yellow_bg\">possible</span>.</li></ul></div>"},{"i":"0a12708ae3cb","n":186,"o":"186-5","u":"Physiopathologie","t":"Connaître les éléments physiopathologiques des allergies aux venins d’hyménoptères : prévalence, mortalité","q":"Faut-il attendre un grade III de Mueller pour traiter une anaphylaxie ?","a":"<div class=\"notion-course\"><ul><li>Non. L’<span class=\"nc-pink nc-bold\">adrénaline IM</span> dépend du diagnostic clinique d’anaphylaxie, sans attente d’un grade élevé.</li></ul></div>"},{"i":"f4c98423fcee","n":186,"o":"186-8","u":"Diagnostic positif","t":"Connaître l’algorithme de prise en charge diagnostique et thérapeutique de l’allergie alimentaire IgE-dépendante à l’arachide et aux fruits à coque","q":"Ara h 2 positif prédit-il la gravité de la prochaine réaction ?","a":"<div class=\"notion-course\"><ul><li>Non. Il renforce le diagnostic dans le bon contexte mais ne donne pas une prédiction individuelle certaine de gravité.</li></ul></div>"},{"i":"5804750c1f7c","n":186,"o":"186-9","u":"Diagnostic positif","t":"Connaître l’algorithme de prise en charge diagnostique et thérapeutique de l’allergie alimentaire aux allergènes croisant avec les pneumallergènes","q":"Une sensibilisation PR-10 autorise-t-elle toute réintroduction cuite à domicile ?","a":"<div class=\"notion-course\"><ul><li>Non. La tolérance est souvent meilleure après cuisson, mais le risque dépend de l’histoire et de l’<span class=\"nc-red nc-bold\">aliment</span> ; encadrer si réaction sévère.</li></ul></div>"},{"i":"964880035764","n":186,"o":"186-10","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies aux venins d’hyménoptères","q":"Une tryptase basale > 20 ng/mL suffit-elle à diagnostiquer une mastocytose ?","a":"<div class=\"notion-course\"><ul><li>Non. C’est un argument à interpréter dans un bilan spécialisé ; une valeur normale ne l’exclut pas.</li></ul></div>"},{"i":"dade7a9fb5a5","n":186,"o":"186-12","u":"Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Que signifie un panel multiallergénique positif ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red nc-bold\">Sensibilisation</span> à au moins un allergène du mélange ; il ne désigne pas seul la cause clinique.</li></ul></div>"},{"i":"b4743f74375a","n":186,"o":"186-13","u":"Prise en charge","t":"Connaître les modalités de réalisation et de prescription des tests cutanés en allergologie","q":"Prick et patch évaluent-ils le même mécanisme ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-brown_bg nc-bold\">Non</span>. Prick : réponse immédiate IgE ; patch : <span class=\"nc-red nc-bold\">hypersensibilité</span> <span class=\"nc-red nc-bold\">retardée</span>, notamment <span class=\"nc-pink nc-bold\">eczéma de contact</span>.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181868282e3ed9df680ca?pvs=204","reviewedAt":"2026-10-14","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","algorithms":3,"sddStatus":"Attendus LiSA 2026 consultés le 14 octobre 2026 ; navigation par recherche du numéro de SDD.","lisaSituations":[{"number":299,"title":"Consultation après une réaction allergique","url":"https://livret.uness.fr/lisa/2026/Sp%C3%A9cial:Recherche/SDD-299","expectations":["Reconstituer l’événement, orienter le bilan et prévenir les réexpositions à risque."],"verifiedAt":"2026-10-14","linkType":"number-search"},{"number":203,"title":"Examens allergologiques","url":"https://livret.uness.fr/lisa/2026/Sp%C3%A9cial:Recherche/SDD-203","expectations":["Prescrire des tests dirigés, interpréter sensibilisation et histoire clinique, éviter les bilans indiscriminés."],"verifiedAt":"2026-10-14","linkType":"number-search"}]}};
